from blueprint import *
STEPS={}
def add(code,why,inputs,actions,controls,result,next=None,attention='',role=None,doc=None,when=None):
 g=code[0];n=int(code[1:]);default_next=f'{g}{n+1:02d}' if n<len(TITLES[g]) else {'F':'A04','C':'V01','A':'S02','S':'C08'}[g]
 defaults={'F':('Responsable stock / achats','Purchase Receipt / Serial No'),'C':('Utilisateur commercial habilité','Quotation / Sales Order'),'A':('Opérateur ou responsable atelier habilité','Material Cutting Plan / UX 2.0'),'S':('Responsable stock habilité','Stock Entry · Repack')}
 sources=SOURCE_MAP.get(code,SOURCE_MAP.get(g,['mat_reco/fixtures/custom_field.json']))
 STEPS[code]={'id':code,'title':title(code),'group':g,'why':why,'objective':result,'inputs':inputs,'actions':actions.split('|'),'controls':controls.split('|'),'result':result,'next':next or default_next,'attention':attention,'role':role or defaults[g][0],'document':doc or defaults[g][1],'when':when or 'Au passage indiqué du flux, après contrôle des entrées nécessaires.','sources':sources,'evidence':'Procédure proposée à valider' if code in ['F01','F03','C01','C08','A28','S14'] else 'Historique · fonctionnement spécifique' if code=='S12' else 'Standard ERPNext · à confirmer sur site' if code in ['F02','C02','C06','C10','C12','C13'] else 'Fonction mat_reco · déduite du code','exceptions':[e for e,v in EXCEPTIONS.items() if code in v[0] or any(code.startswith(t.split('–')[0]) for t in [])]}
# Fournisseur
add('F01','Éviter de lancer la découpe sans matière adaptée. La demande d’achat vient d’un besoin à produire ou du réapprovisionnement.','Besoins dimensionnés ; stock disponible ; politique d’achat.','Lire les quantités à produire.|Comparer le stock utile dans le dépôt prévu.|Définir matière, épaisseur et quantité à approvisionner.','Article PRIMAIRE correct.|Dimension utile et épaisseur compatibles.|Quantité à acheter justifiée.','Matière à acheter définie.','F02 ou F05 selon circuit',doc='Demande d’approvisionnement / Item / stock',attention='Le besoin d’achat n’est pas un rectangle déjà disponible au MCP.')
add('F02','Donner au fournisseur une commande traçable avant réception, lorsque le circuit achat le prévoit.','Fournisseur, société, article, quantité, prix et date attendue.','Créer Purchase Order selon la procédure achat.|Renseigner les lignes et le dépôt prévu.|Contrôler les spécifications de matière et les dates.|Enregistrer puis soumettre selon les droits.','Fournisseur et société.|Quantité et unité d’achat.|Dimensions dans l’article ou la spécification d’achat.','Purchase Order prêt à être réceptionné.','F03',doc='Purchase Order',attention='mat_reco n’impose pas Purchase Order à toutes les réceptions. Des colonnes de dimensions sur PO ne sont pas confirmées par les fixtures du module.')
add('F03','Vérifier que ce qui arrive correspond à ce qui sera enregistré en stock.','Livraison physique ; commande ou justificatif ; article attendu.','Compter les plaques.|Mesurer longueur, largeur et épaisseur.|Constater la qualité et les éventuels dommages.|Choisir le circuit de réception avant saisie.','Quantité livrée contre quantité attendue.|Dimensions réelles.|Plaques détériorées identifiées.','Livraison fournisseur contrôlée.','F04 ou F05',doc='Contrôle physique / justificatif',attention='Cette fiche est une procédure atelier proposée, pas un contrôle physique automatisé dans ERPNext.')
add('F04','Constater la réception fournisseur et rendre les unités disponibles, avec leurs séries.','Article sérialisé ; dépôt ; dimensions ; bundle / séries ; PO si applicable.','Depuis PO soumis, utiliser Create → Purchase Receipt si disponible, ou ouvrir le chemin réception autorisé.|Contrôler les quantités et le dépôt.|Renseigner dimensions et séries / bundle.|Enregistrer et soumettre selon la procédure stock.','Longueur et largeur positives.|Sérialisation de l’article reconfigurable.|Séries réellement reçues dans le dépôt.','Réception d’achat enregistrée et séries à contrôler.','F07',doc='Purchase Receipt',attention='L’activation des scripts de report des dimensions est à confirmer. Ne pas dupliquer cette réception avec F05.')
add('F05','Préparer une réception dimensionnée PRIMAIRE ou DECOUPE quand le circuit retenu n’utilise pas F04 pour ces unités.','Société, dépôt cible, article, quantité entière, montant et dimensions.','Créer Material Receipt Plan.|Renseigner Quantity et Amount.|Contrôler les lignes : PRIMAIRE reprend Item ; DECOUPE permet des dimensions par unité.|Enregistrer puis soumettre le plan après contrôle.','Une ligne par série.|Longueur, largeur et épaisseur positives.|Total surface et somme des valeurs cohérents.','Séries créées et entrée Material Receipt soumise.','F07',doc='Material Receipt Plan',attention='Soumettre le plan crée et soumet le mouvement. Basic Rate représente ici la valeur de l’unité, pas un prix par m².')
add('F06','Choisir un seul chemin pour une même réception et éviter deux entrées de stock pour les mêmes plaques.','Nature de l’approvisionnement ; procédure stock ; justificatif.','Identifier si les unités passent par Purchase Receipt.|Si le circuit autorisé est dimensionné hors ce chemin, utiliser Material Receipt Plan.|Ne pas ressaisir les mêmes unités dans l’autre document.','Le justificatif correspond au document choisi.|Une seule entrée réelle par unité.|Commande fournisseur non supposée obligatoire partout.','Circuit approprié identifié.','F04 ou F05',doc='Purchase Receipt / Material Receipt Plan',attention='Les deux circuits convergent vers Serial No et stock ; ils ne sont pas deux étapes successives obligatoires.')
add('F07','Chaque plaque doit rester identifiable après réception et durant sa transformation.','Réception soumise ; identifiants de séries et bundle.','Lire les séries du mouvement réception.|Ouvrir les Serial No concernés.|Comparer le nombre de séries au nombre d’unités reçues.','Article de la série.|Absence de doublon.|Les identifiants prévus sont bien devenus des séries réelles.','Plaques identifiées.','F08',doc='Serial No / Serial and Batch Bundle')
add('F08','Une plaque au mauvais format ou de mauvaise qualité ne doit pas être utilisée par erreur.','Fiche Serial No ; plaque physique ; spécification de matière.','Comparer dimensions et épaisseur à la plaque.|Contrôler état matériel et qualité.|Faire corriger une incohérence de réception par le responsable avant planification.','Dimensions positives.|Épaisseur compatible.|État Full / Partial et matière utile correcte.','Matière physiquement qualifiée.','F09',doc='Serial No',attention='Les champs et le report d’épaisseur doivent être contrôlés sur le site ; ne pas inventer une valeur pour rendre une plaque admissible.')
add('F09','Le MCP doit trouver une matière réellement disponible dans son dépôt, pas une simple série prévue.','Séries contrôlées ; dépôt source du futur MCP.','Vérifier l’entrepôt et le mouvement soumis.|Contrôler la disponibilité des séries.|Mettre à disposition les informations matière pour A04 / A05.','Dépôt de la société.|Séries admissibles Full / Partial.|Aucune série déjà consommée dans la sélection.','Stock utilisable par le MCP.','A04 / A05',doc='Serial No / stock candidat',attention='Un nom de série prévu pour une sortie ne prouve pas que la sortie est déjà disponible en stock.')
# Client
add('C01','Définir ce que le client attend avant de calculer un devis ou un plan de découpe.','Client ; demande ; dimensions ; quantités ; finition souhaitée.','Identifier découpe simple ou ouvrage composé.|Confirmer les dimensions et l’épaisseur.|Préciser services, accessoires et quantité.','Nature de l’article.|Dimensions finales attendues.|Quantité commerciale claire.','Nature du besoin définie.','C02',doc='Demande client / Quotation')
add('C02','Conserver la demande, les prix et les conditions dans un document commercial.','Client, société, articles et besoin confirmé.','Créer Quotation.|Renseigner les lignes et quantités.|Saisir les dimensions et services des étapes C03 / C04.|Contrôler et enregistrer le devis.','Client et validité du devis.|Articles corrects.|Conditions de vente selon procédure.','Quotation préparée.','C03',doc='Quotation')
add('C03','Les dimensions client guident la découpe et les contrôles de conformité.','Ligne DECOUPE ou OUVRAGE ; quantité finale.','Saisir longueur, largeur / hauteur et épaisseur en mm.|Vérifier la quantité de la ligne.|Contrôler le nom et la description dimensionnés lorsque les scripts les complètent.','Valeurs positives.|Aucune confusion mm / m.|Dimensions et quantité reprises dans la commande.','Besoin dimensionné.','C04 / C06',doc='Quotation Item / Sales Order Item',attention='Les contrôles devis et commande ne sont pas identiques : contrôler l’épaisseur même si un formulaire ne bloque pas sa saisie.')
add('C04','Associer à la ligne principale les prestations et accessoires qui complètent le besoin.','Ligne parent DECOUPE ou OUVRAGE avec dimensions et quantité.','Ouvrir Services / Accessoires sur la ligne si le bouton est actif.|Filtrer les éléments et lire la base de calcul.|Contrôler les quantités finales.|Sélectionner et insérer les lignes voulues.','Lien à la ligne parent.|SURFACE / PERIMETRE / PIECE / FIXE / MANUEL.|Prix et quantités après insertion.','Devis complet.','C06',doc='Quotation · Services / Accessoires',attention='Le calcul part de la ligne parent. Il ne multiplie pas automatiquement le périmètre par tous les composants internes d’un ouvrage.')
add('C05','La structure des articles permet au système de convertir un ouvrage en découpes.','Item de matière ; DECOUPE ; composants et facteurs d’OUVRAGE.','Faire contrôler les types PRIMAIRE, DECOUPE et OUVRAGE.|Vérifier Parent Item de la découpe.|Vérifier les composants et Qty Factor de l’ouvrage.','Descendance de la matière source.|Facteurs de quantité.|Absence de références circulaires.','Besoin correctement structuré.','C02 / C06',role='Responsable métier / administrateur articles',doc='Item / Composite Item Detail',attention='Le paramétrage d’article est un prérequis. L’opérateur ne doit pas modifier les composants pour contourner une rupture de stock.')
add('C06','Confirmer le besoin commercial qui alimentera l’atelier et la livraison.','Devis contrôlé ; droits ; validation commerciale.','Soumettre le devis selon la procédure.|Utiliser Create → Sales Order si disponible.|Contrôler lignes, dimensions, quantités et références.|Enregistrer puis soumettre la commande selon les droits.','Validité et état du devis.|Dimensions conservées.|Bonne ligne de commande associée au produit.','Sales Order confirmée.','C07',doc='Quotation → Sales Order',attention='ERPNext permet d’autres chemins de création de commande. Le parcours présenté ne les interdit pas.')
add('C07','Transmettre au Flux 3 un besoin unitaire de découpe, lié à la commande.','Sales Order ; article et composants ; matière source.','Identifier la ligne à produire.|Vérifier l’explosion des composants en DECOUPE.|Passer à A01 puis sélectionner la commande dans le MCP.','Référence Sales Order et ligne.|Quantité commerciale versus nombre de composants.|Matière source compatible.','Besoins disponibles pour le MCP.','A01 — entrer dans le Flux 3',doc='Sales Order → MCP',attention='Le flux commercial exprime le besoin ; il ne découpe pas lui-même les plaques.')
add('C08','Reprendre le flux commercial uniquement après contrôle des résultats atelier et stock.','Retour S14 ; plan effectif ; mouvements soumis et besoins restants.','Lire le bilan de production.|Comparer quantités conformes et quantités demandées.|Faire traiter une insuffisance par A19 / A24.|Passer à C09 si les produits sont réellement disponibles.','Couverture du besoin.|Pièce détruite non comptée.|Recomposition achevée si l’article livré est un ouvrage.','Couverture des quantités connue.','C09 ou retour A19',doc='Sales Order / MCP / Repack',attention='Ce chapitre ne suppose pas un tableau automatique de suivi fabrication qui n’a pas été confirmé sur le site.')
add('C09','Éviter de livrer une prévision ou une pièce qui n’est pas dans l’entrepôt.','Produits ou ouvrages après Repack soumis.','Vérifier article et quantité disponibles.|Contrôler les Serial No dans le dépôt de livraison.|Préparer la sélection de séries / bundle.','Produit conforme.|Entrepôt correct.|Aucune série déjà sortie.','Pièces / ouvrages prêts à livrer.','C10',role='Responsable stock / expédition',doc='Serial No / Stock Entry / stock')
add('C10','Constater les produits remis au client selon la procédure de livraison.','Commande ; produits disponibles ; séries / bundle ; dépôt.','Depuis Sales Order, utiliser Create → Delivery Note si autorisé.|Contrôler les lignes et quantités livrées.|Associer les séries / bundles corrects.|Enregistrer et soumettre après contrôle.','Quantité réellement livrée.|Dépôt source.|Référence de commande.','Delivery Note soumise.','C11 puis C12',role='Responsable expédition / stock',doc='Delivery Note',attention='La livraison de notre parcours principal est distincte de la facture. Contrôler les variantes site avant un autre chemin.')
add('C11','Relier la livraison aux unités physiques et aux dimensions effectivement remises.','Delivery Note ; bundle de ses lignes ; Serial No.','Ouvrir le bundle.|Comparer chaque série à la livraison.|Vérifier longueur, largeur et épaisseur affichées sur les DECOUPE.','Groupement homogène.|Première série utilisée par le report de dimensions.|Article, série et commande cohérents.','Traçabilité de livraison contrôlée.','C12',role='Responsable expédition / stock',doc='Delivery Note Item / Serial and Batch Bundle',attention='Le report mat_reco depuis la première série vise DECOUPE. Ne pas généraliser ce comportement à OUVRAGE sans confirmation.')
add('C12','Facturer le parcours commercial avec ses références et quantités livrées.','Delivery Note contrôlée ; droits ; conditions de facturation.','Utiliser Create → Sales Invoice sur la livraison si disponible.|Contrôler les lignes et références reprises.|Vérifier le traitement stock de la facture avant validation.','Client.|Références de livraison et commande.|Quantité à facturer.','Sales Invoice préparée.','C13',role='Utilisateur facturation habilité',doc='Delivery Note → Sales Invoice',attention='Livraison → Facture est notre chemin pédagogique, pas une obligation universelle ERPNext. Les chemins directs depuis Sales Order restent à valider.')
add('C13','Terminer le cycle sans incohérence de quantité, de valeur ou de mouvement de stock.','Facture préparée ; commande et livraison de référence.','Comparer quantités, montants et références.|Contrôler dimensions et descriptions utiles.|Vérifier Update Stock au regard de la livraison déjà constatée.|Soumettre la facture selon la procédure de facturation.','Aucune double sortie des mêmes unités.|Conditions et montants approuvés.|Traçabilité vers le client.','Cycle commercial complété.','V01 — contrôle final',role='Utilisateur facturation / responsable',doc='Sales Invoice',attention='Le paiement et les régimes fiscaux ne sont pas traités par ce manuel mat_reco.')
# Atelier
add('A01','Transformer la commande en pièces unitaires à positionner, sans perdre son identité commerciale.','Passage C07 ; commandes dimensionnées ; hiérarchie d’articles.','Lire les découpes issues des commandes.|Multiplier les composants d’ouvrage par leur quantité.|Contrôler matière et dimensions attendues.','Unité commerciale identifiée.|Dimensions et épaisseur.|Quantité de découpes versus quantité d’ouvrages.','Liste des découpes connue.','A02',doc='Sales Order / besoins MCP')
add('A02','Rassembler les besoins et la matière dans un plan de découpe traçable.','Société ; dépôt ; article source PRIMAIRE.','Créer Material Cutting Plan.|Choisir Company, Source Warehouse et Source Item.|Laisser Mode à Planification.|Contrôler les variantes admises.','Dépôt de la société.|Source PRIMAIRE.|Périmètre matière clair.','MCP en préparation.','A03',doc='Material Cutting Plan')
add('A03','Limiter le calcul aux commandes à traiter pendant cette préparation.','MCP avec Source Item ; commandes liées à cette matière.','Dans Outils, choisir Select Orders for Source Item.|Lire les commandes proposées.|Conserver le périmètre voulu.','Bonne commande.|Bonne matière parent.|Quantité demandée.','Commandes sélectionnées.','A04')
add('A04','Présenter au calcul les séries utilisables, dans le dépôt choisi.','Source Item ; Source Warehouse ; variantes.','Choisir Get Stock.|Contrôler les séries et dimensions chargées.|Actualiser si le stock a changé.','Séries Full / Partial.|Dimensions positives.|Épaisseur et dépôt cohérents.','Serial No candidats chargés.','A05',attention='Les lignes chargées sont initialement qualifiées : revoir cette sélection avant calcul.')
add('A05','Autoriser le calcul à utiliser uniquement les matières que l’atelier accepte.','Table MCP Stock Candidate ; matière physique contrôlée.','Relire chaque plaque ou chute.|Cocher / décocher Is Qualified selon le choix voulu.|Enregistrer avec la sélection vérifiée.','Is Qualified : admissible au calcul.|Is Active Input : réellement utilisé.|Les deux colonnes ne sont pas interchangeables.','Matières admissibles définies.','A06',attention='Qualifier une série ne constitue pas une consommation de stock.')
add('A06','Prendre en compte les pertes de coupe et les options d’optimisation initiale.','Valeur kerf réelle ; contraintes atelier ; choix du responsable.','Renseigner Kerf mm.|Choisir Allow Rotation pour la Planification.|Contrôler algorithme, heuristique et profondeur si nécessaire.','Unités mm.|Trait de coupe réaliste.|Options adaptées aux pratiques de l’atelier.','Paramètres de découpe contrôlés.','A07',attention='Les scènes illustrées peuvent simplifier le kerf à 0. Ce n’est pas une recommandation de production ; utiliser la valeur réelle de l’atelier.')
add('A07','Visualiser comment la matière proposée satisfait les commandes avant la coupe.','MCP avec commandes, stock et paramètres.','Enregistrer pour générer le plan.|Parcourir les plaques.|Comparer demandé, planifié, manquant et restes.','Pièces positionnées.|Matières réellement utilisées.|Absence de besoin oublié.','Plan initial lisible et contrôlé.','A08',attention='Le dessin d’optimisation ne certifie pas toutes les contraintes physiques de votre machine.')
add('A08','Éviter de traiter un déchet ou une encoche comme une chute disponible.','Plan initial ; légende de l’atelier.','Repérer les produits finis bleus.|Identifier chutes grises, chutes en L vertes et déchets roses.|Lire les dimensions et la plaque courante.','Zone occupée différente d’une zone libre.|Surface utile d’une chute en L.|Zoom sans effet sur dimensions.','Lecture correcte du dessin.','A09')
add('A09','Conserver la Planification de référence et décrire ensuite les résultats réels de coupe.','Plan initial enregistré ; début des constats terrain.','Passer Mode à Retour Terrain.|Enregistrer le formulaire.|Vérifier que le plan effectif est disponible.','MCP brouillon.|Plan de Planification conservé.|Formulaire sans modification non enregistrée.','MCP prêt aux incidents.','A10',doc='Material Cutting Plan · Retour Terrain')
add('A10','Accéder à la géométrie et aux actions dans l’écran atelier.','MCP enregistré ; mode Retour Terrain ; droits.','Choisir Interface → UX 2.0 ou agrandir l’aperçu.|Vérifier la plaque affichée.|Repérer dessin à gauche et informations à droite.','Référence MCP.|Une plaque à la fois.|État d’enregistrement.','Interface de travail ouverte.','A11',doc='Atelier UX 2.0')
add('A11','Préparer une action sur la bonne unité ou zone physique.','Plaque courante ; pièce / chute / déchet à traiter.','Cliquer la zone.|Lire ses dimensions.|Choisir dans le menu une action autorisée.','Bonne plaque et bonne unité.|Menus selon type de zone.|Curseur d’action et cible compatible.','Action préparée.','A12–A17 selon constat',doc='Atelier UX 2.0 · menu contextuel',attention='Le curseur d’interdiction indique une cible incompatible, pas une défaillance du menu.')
add('A12','Replacer une pièce dans une zone libre sans créer une autre unité commerciale.','Produit fini source ; chute compatible sur la même plaque ou une autre.','Sélectionner la pièce puis Déplacer.|Changer de plaque si nécessaire.|Choisir la cible libre.|Comparer puis confirmer.','Espace suffisant.|Source libérée.|Identité de pièce conservée.','Nouvelle position prévisualisée.','A18',attention='Ne pas déplacer la pièce sur une zone détruite, occupée ou dans une encoche retirée.')
add('A13','Utiliser un format de chute compatible en permutant les deux côtés de la pièce.','Action Déplacer ; pièce et destination ; place utile.','Dans Orientation, choisir Automatique, Actuelle ou Tourner à 90°.|Lire les dimensions résultantes.|Contrôler le placement sur la cible.|Confirmer la proposition.','800 × 600 devient 600 × 800 dans l’exemple.|Aucun empiétement.|Orientation conforme au constat physique.','Orientation corrigée.','A18',attention='La rotation à 90° est disponible en Retour Terrain même si Allow Rotation était décoché en Planification. Automatique essaie d’abord l’orientation actuelle.')
add('A14','Décrire une dimension effectivement réduite sans la confondre avec une nouvelle commande.','Zone dont le menu propose Redimensionner ; mesure réelle.','Choisir Redimensionner.|Saisir longueur et largeur.|Comparer la réduction et ses compléments.|Confirmer.','Valeurs positives.|Pas d’agrandissement au-delà de la matière source.|Besoin client encore satisfait ou à compenser.','Dimensions effectives prévisualisées.','A18',attention='Une pièce plus petite peut ne plus couvrir le besoin initial. Relire le bilan après application.')
add('A15','Déclarer qu’une pièce n’est plus utilisable et déterminer si elle doit être remplacée.','Pièce cassée ou zone inutilisable identifiée.','Sélectionner la pièce.|Choisir Détruire.|Vérifier la surface indisponible.|Choisir Confirmer la destruction.','Bonne pièce et bonne commande.|Zone conservée comme occupée.|Exclusion des sorties conformes.','Incident de casse confirmé dans la session.','A18 puis A19',attention='Une zone détruite ne redevient pas une chute libre. Détruire ne crée pas automatiquement le remplacement.')
add('A16','Conserver une chute rectangulaire en réunissant des régions libres contiguës.','Chute source ; zone libre adjacente sur la même plaque.','Choisir Fusionner.|Sélectionner le donneur compatible.|Vérifier la chute étendue et le reste du donneur.|Confirmer.','Même plaque.|Union rectangulaire.|Aucune matière retirée réintroduite.','Chute rectangulaire prévisualisée.','A18',attention='Le donneur peut conserver un reste ; vérifier qu’il ne disparaît pas dans votre lecture du dessin.')
add('A17','Représenter une seule chute physique en L avec son encoche conservée.','Deux régions libres compatibles ; au moins une chute.','Choisir Chute en L.|Sélectionner la deuxième zone.|Contrôler l’encoche supérieure gauche et la surface utile.|Confirmer.','Exactement deux zones.|Contiguïté.|L’encoche reste indisponible.','Leftover physique unique prévisualisé.','A18',attention='Le grand rectangle extérieur n’est pas entièrement disponible pour une nouvelle coupe.')
add('A18','Séparer le choix local d’une opération de son enregistrement auprès du serveur.','Opération valide ; aperçu ; MCP brouillon.','Comparer Avant / Après / Superposer.|Confirmer l’action ou l’annuler.|Choisir Appliquer à l’aperçu → pour les incidents.|Attendre le succès d’enregistrement.','Message de réussite.|Version courante.|Pas d’opération encore active à appliquer.','Incidents enregistrés.','A19',attention='Confirmer seul ne suffit pas. Un conflit nécessite de recharger et reprendre sur le plan courant.')
add('A19','Mesurer ce qui reste dû au client après les incidents, sans compter une casse comme une production.','Plan effectif et incidents enregistrés ; besoin commercial.','Comparer unités conformes et unités requises.|Identifier les unités à remplacer.|Si un besoin reste, ouvrir la compensation.','Commande et unité commerciale.|Remplacements conformes seulement.|Aucune série prévue comptée comme réception exécutée.','Bilan après incidents connu.','A20 si besoin ; sinon A26')
add('A20','Ouvrir la recherche des remplacements sans quitter la disposition de l’atelier.','MCP Retour Terrain brouillon ; incidents appliqués.','Cliquer Compenser près de Réinitialiser.|Lire dimensions et quantité à compenser.|Lire les sources de stock à droite.|Choisir Automatique ou Manuel.','Bonne commande.|Stock admissible.|Mode de compensation.','Session de compensation ouverte.','A21 / A22 / A23 selon source',attention='L’ajout matière est sélectionné dans le panneau de stock ; le dessin reste une plaque par page.')
add('A21','Réutiliser la matière interne disponible avant d’ajouter du stock.','Chute interne utile ; besoin restant ; calcul de compensation.','Garder Automatique pour respecter la priorité.|Choisir Calculer.|Parcourir les placements proposés sur le MCP.','Pièce passe avec orientation permise.|Aucune pièce conforme modifiée.|Chute et reste cohérents.','Compensation interne proposée.','A24',attention='La priorité interne ne dispense pas de vérifier dimensions, épaisseur et matière déjà consommée.')
add('A22','Remplacer une unité quand les chutes du plan ne suffisent pas.','Chute stock disponible ; dépôt, matière, épaisseur compatibles.','Actualiser le stock si nécessaire.|Laisser le calcul automatique chercher une chute, ou sélectionner la source en Manuel.|Calculer et ouvrir la plaque ajoutée.','Origine stock.|Surface ET dimensions utiles.|Rotation autorisée en Retour Terrain.','Matière supplémentaire sélectionnée.','A24',attention='Si un choix manuel écarte une source prioritaire, justifier ce contournement.')
add('A23','Utiliser une plaque entière lorsque les chutes admissibles ne couvrent pas le reste.','Besoin restant ; plaque entière disponible et compatible.','Laisser l’automatique rechercher la priorité 3 ou sélectionner une source admissible.|Calculer.|Contrôler la plaque ajoutée et ses nouveaux restes.','Plaque entière réellement disponible.|Unités remplacées.|Consommation additionnelle justifiée.','Entrée complémentaire proposée.','A24',attention='Une plaque entière est une nouvelle matière à intégrer au futur Repack ; ne pas la confondre avec une simple page d’affichage.')
add('A24','Enregistrer uniquement une proposition contrôlée qui remplace les bonnes unités.','Proposition calculée ; sources encore disponibles.','Contrôler placements, besoins restants et avertissements.|Choisir Valider la compensation si le résultat convient.|Attendre la confirmation serveur et le retour atelier.|Ou Annuler pour revenir sans application.','Couverture.|Version document et stock.|Pas de soumission automatique MCP / Stock Entry.','Besoin compensé selon proposition confirmée.','A26',attention='Calculer ne sauvegarde pas. Une compensation peut laisser des besoins restants : ne pas forcer la clôture.')
add('A25','Garder la trace d’une nouvelle casse sur un remplacement sans dupliquer la demande client.','Remplacement identifié ; nouveau constat de casse.','Créer un nouvel incident sur la pièce concernée.|Confirmer et appliquer.|Relire le besoin restant.|Recalculer une compensation adaptée.','Opérations antérieures conservées.|Une seule unité commerciale due.|Production / consommation déjà soumises figées.','Reprise de production traçable.','A19',attention='Ne pas supprimer les événements précédents pour fabriquer une seconde demande ; solliciter le responsable si la pièce est déjà engagée dans un Repack soumis.')
add('A26','Préparer le stock à partir du résultat enregistré, pas d’une prévisualisation abandonnée.','Plan effectif enregistré ; couverture et géométrie.','Parcourir les plaques utilisées et ajoutées.|Comparer conformes, remplacements et besoins.|Contrôler les restes et les zones détruites.','Toutes les unités dues couvertes.|Surface physique conservée.|Bonnes matières actives.','Plan effectif cohérent.','A28 ou A27 si restauration voulue')
add('A27','Restaurer la référence juste après Planification quand la réinitialisation est appropriée.','MCP brouillon ; décision de restauration ; absence de Repack soumis lié.','Cliquer Réinitialiser.|Lire le message de suppression.|Annuler pour conserver l’état, ou confirmer.|Contrôler le plan initial et les incidents supprimés.','Portée complète comprise.|Historique vidé après succès.|Conflit ou production soumise bloque la suppression.','Retour au plan initial.','A07',attention='Supprime les incidents sauvegardés et en attente ainsi que les compensations. Ne relance pas l’optimisation et ne peut pas être annulé depuis l’historique.')
add('A28','Clôturer les contrôles atelier sans inventer un ordre de soumission ERP non validé.','Plan effectif ; besoin couvert ; droits ; procédure interne.','Appliquer les incidents et contrôler les résultats.|Faire vérifier la couverture par le responsable.|Choisir le circuit de soumission MCP / Repack approuvé sur le site.','Besoins non couverts bloquants.|Document prêt pour les contrôles stock.|Responsable de validation connu.','Plan contrôlé pour la phase stock.','S01 / S02',attention='L’ordre exact de soumission MCP et Repack reste une décision ouverte. La soumission MCP verrouille les modifications atelier.')
# Stock / transformation réelle
add('S01','Comprendre quand une prévision de découpe devient une consommation et une production de stock.','Plan effectif enregistré ; séries source et sorties attendues.','Identifier les entrées à consommer.|Identifier les pièces, chutes et éventuels déchets à produire.|Distinguer plan, brouillon Repack et mouvement soumis.','Un Repack par transformation contrôlée.|Bonne société.|Séries traçables.','Entrées et sorties identifiées.','S02',attention='Le Repack de découpe et celui de recomposition d’un ouvrage sont deux transformations distinctes.')
add('S02','Préparer les lignes de Stock Entry à partir du plan effectif sauvegardé.','MCP enregistré ; incidents appliqués ; formulaire non modifié.','Choisir Create Draft Repack.|Ouvrir la Stock Entry préparée.|Contrôler type Repack et lien au MCP.|Enregistrer le brouillon pour les contrôles.','Résultat effectif chargé.|Aucun doublon de sorties.|Aucune soumission automatique.','Stock Entry brouillon.','S03')
add('S03','Consommer les unités qui ont réellement fourni la matière au plan.','Repack brouillon ; plan effectif ; séries disponibles.','Lire les lignes avec entrepôt source.|Vérifier article, quantité et séries.|Contrôler le bundle et la disponibilité.','Dépôt source.|Séries encore disponibles.|Pas de deuxième consommation d’une entrée déjà soumise.','Serial No d’entrée contrôlés.','S04')
add('S04','Produire seulement les pièces conformes au besoin et à l’état effectif.','Repack ; pièces et remplacements du plan.','Lire les lignes avec entrepôt cible.|Comparer quantité et dimensions au plan effectif.|Vérifier les identifiants de sorties et la commande.','Pièces détruites exclues.|Quantités dues.|Identité commerciale conservée.','Produits finis contrôlés.','S05')
add('S05','Enregistrer les chutes réutilisables avec leur géométrie physique.','Restes du plan ; sorties de Repack ; éventuelles chutes en L.','Contrôler les sorties leftover.|Lire dimensions extérieures et retirées d’un L.|Vérifier la matière utile et le dépôt cible.','Encoche soustraite.|Chute unique si L.|Aucun reste donneur oublié.','Leftovers et chutes en L contrôlés.','S06',attention='Une chute en L ne se valorise ni ne se réutilise comme son rectangle extérieur plein.')
add('S06','Traiter les pertes selon le choix de stock du circuit, sans les faire passer pour des pièces conformes.','Option Add Waiste to stock du MCP ; déchets et destructions.','Lire l’option choisie.|Comparer les déchets du dessin aux sorties prévues.|Vérifier que les destructions restent exclues des produits conformes.','Déchet versus zone détruite.|Quantités / surfaces.|Politique stock validée.','Pertes correctement traitées.','S07',attention='Le libellé anglais livré contient « Waiste ». Ne pas activer l’option pour faire disparaître un écart de surface.')
add('S07','Relier la matière consommée aux pièces, chutes et pertes effectives.','Toutes les lignes du Repack ; plan effectif ; unités de mesure.','Comparer surfaces des entrées.|Comparer sorties, restes et pertes.|Exclure les encoches déjà retirées des surfaces utiles.','mm² / m² cohérents.|Pertes de coupe.|Toutes les plaques et sources ajoutées prises en compte.','Bilan matière contrôlé.','S08',attention='Le nombre de séries et la surface sont deux contrôles différents ; une ligne regroupée peut porter plusieurs unités.')
add('S08','Préserver la cohérence de valorisation de la matière transformée.','Valeurs d’entrée ; surfaces utiles ; lignes de Repack.','Contrôler les coûts d’entrée.|Lire la répartition des coûts sur les sorties.|Faire vérifier les arrondis et toute valeur nulle.','Valeur d’entrée non nulle pour la répartition.|Surface utile des L.|Aucune correction manuelle sans analyse.','Valorisation cohérente.','S09',attention='Les règles de coût sont des fonctions du module ; leur recette complète en mouvements soumis reste à valider sur le site.')
add('S09','Constater le mouvement de consommation et de production réellement effectué.','Brouillon contrôlé S03–S08 ; droits et validations internes.','Revoir société, date et séries.|Enregistrer le Stock Entry.|Soumettre selon procédure.|Vérifier le mouvement et les séries disponibles.','Doublons interdits.|Quantités / limites du MCP.|Bundles et valeurs cohérents.','Mouvement de stock réel.','S10 si recomposition ; sinon S13',attention='La soumission Stock Entry et celle du MCP sont distinctes. Un brouillon seul ne rend pas les produits disponibles.')
add('S10','Transformer des découpes déjà disponibles en produit / ouvrage de la ligne de commande.','Pièces en stock ; Sales Order avec quantité restante.','Ouvrir une Stock Entry brouillon Repack avec Company.|Choisir Get Pending SO Line.|Lire restant et satisfaisable ; sélectionner une ligne.|Créer le Repack proposé et contrôler ses lignes.','Quantité ne dépasse pas le restant.|Stock couvre les composants.|Circuit actif Create Repack ou variante Generate Repack.','Repack de recomposition préparé.','S11',doc='Stock Entry · Get Pending SO Line',attention='Ce Repack ne doit pas consommer une deuxième fois la plaque du Repack de découpe.')
add('S11','Vérifier que l’ouvrage est produit avec la totalité des composants conformes.','Repack de recomposition ; structure d’Item ; séries composantes.','Comparer composants et Qty Factor.|Vérifier quantité et dimensions des pièces allouées.|Contrôler dépôts et sorties ouvrage.|Soumettre selon les mêmes contrôles stock appropriés.','Composants complets.|Article et dimensions exacts.|Quantité d’ouvrage réellement réalisable.','Produit composite contrôlé et produit selon procédure.','S13',attention='Si le stock ne couvre qu’une partie de la commande, la quantité satisfaisable limite la génération. Ne pas ignorer un composant manquant.')
add('S12','Connaître un circuit ancien sans le mélanger avec le MCP UX 2.0.','Material Reconfiguration ; commande ; produit ; matière.','Lire le plan proposé et les lignes Detail.|Contrôler un éventuel plan partiel.|Soumettre uniquement selon le circuit historique validé.|Utiliser Create Repack (New, Bundled) pour le Stock Entry associé.','Raw Material / Finished Good / By Product.|Changement d’état de séries à la soumission historique.|Annulation spécifique.','Circuit historique identifié.','S13 si ce circuit est retenu',doc='Material Reconfiguration',attention='Ce document a une logique de soumission / annulation distincte. La procédure Réinitialiser du MCP ne s’y applique pas.')
add('S13','Relier les nouvelles unités à la matière consommée et au mouvement exécuté.','Repack soumis ; Serial No et bundles de sortie.','Ouvrir les séries produites.|Vérifier article, dimensions et dépôt.|Lire liens MCP, mouvement, parent et racine quand renseignés.','Série réellement produite.|Liens présents et cohérents.|Pas de confusion nom prévu / unité disponible.','Traçabilité de production contrôlée.','S14',doc='Serial No / Serial and Batch Bundle')
add('S14','Redonner au Flux Client un résultat livrable, pas une promesse de fabrication.','Pièces ou ouvrages conformes ; mouvement soumis ; disponibilité.','Vérifier quantité disponible.|Identifier les unités livrables.|Transmettre les références au responsable livraison.|Reprendre le flux commercial en C08.','Bonne commande.|Bon article livré : découpe ou ouvrage.|Dépôt et séries disponibles.','Produits à disposition du client.','C08 / C09 — reprendre le Flux 2',doc='Serial No / stock / Sales Order')
assert set(STEPS)==set(all_codes())
